from bisect import bisect_right


class Plan:
    __slots__ = ('val', 'count', 'indices')

    def __init__(self, val, count, indices):
        self.val = val
        self.count = count
        self.indices = indices

    def is_better_than(self, other):
        if self.val != other.val:
            return self.val > other.val
        if self.count != other.count:
            return self.count < other.count
        return self.indices < other.indices


def best(p1, p2):
    if p1 is None:
        return p2
    if p2 is None:
        return p1
    return p1 if p1.is_better_than(p2) else p2


class BIT:
    def __init__(self, size):
        self.size = size
        self.tree = [None] * (size + 1)

    def update(self, idx, plan):
        while idx <= self.size:
            self.tree[idx] = best(self.tree[idx], plan)
            idx += idx & (-idx)

    def query(self, idx):
        res = None
        while idx > 0:
            res = best(res, self.tree[idx])
            idx -= idx & (-idx)
        return res


def weighted_interval_plan(jobs: list) -> list:
    if not jobs:
        return []

    indexed_jobs = [(job[0], job[1], job[2], i) for i, job in enumerate(jobs)]
    indexed_jobs.sort(key=lambda x: (x[0], x[1], x[3]))

    times = sorted(set(x[0] for x in indexed_jobs) | set(x[1] for x in indexed_jobs))

    bit = BIT(len(times))
    empty_plan = Plan(0, 0, ())
    overall_best = empty_plan

    for s, e, v, idx in indexed_jobs:
        idx_s = bisect_right(times, s)
        prev_plan = best(bit.query(idx_s), empty_plan)

        new_plan = Plan(prev_plan.val + v, prev_plan.count + 1, prev_plan.indices + (idx,))
        overall_best = best(overall_best, new_plan)

        idx_e = bisect_right(times, e)
        bit.update(idx_e, new_plan)

    return list(overall_best.indices)
