def circular_minimax_partition(values: list, groups: int) -> int:
    n = len(values)
    if n == 0:
        return 0
    max_val = max(values)
    total_sum = sum(values)
    if groups == 1:
        return total_sum
    if groups == n:
        return max_val
    doubled = values + values
    num_bits = groups.bit_length()

    def check(M: int) -> bool:
        if max_val > M:
            return False
        nxt = [0] * (2 * n + 1)
        nxt[2 * n] = 2 * n
        right = 0
        cur_sum = 0
        for left in range(2 * n):
            while right < 2 * n and cur_sum + doubled[right] <= M:
                cur_sum += doubled[right]
                right += 1
            nxt[left] = right
            cur_sum -= doubled[left]
        dp = [nxt]
        for b in range(1, num_bits):
            prev = dp[-1]
            curr = [2 * n] * (2 * n + 1)
            for j in range(2 * n):
                curr[j] = prev[prev[j]]
            curr[2 * n] = 2 * n
            dp.append(curr)
        for i in range(n):
            pos = i
            for b in range(num_bits):
                if groups >> b & 1:
                    pos = dp[b][pos]
            if pos >= i + n:
                return True
        return False
    low = max(max_val, (total_sum + groups - 1) // groups)
    high = total_sum
    while low < high:
        mid = (low + high) // 2
        if check(mid):
            high = mid
        else:
            low = mid + 1
    return low

